{"operationName":"SendSmsCode","query":"mutation SendSmsCode($phone: String!) {
  users {
    login {
      otpLogin {
        sendConfirmation(phone: $phone) {
          status
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}
","variables":{"phone":"{{RAW}}"}}
